     */
    extraProps?: React.ButtonHTMLAttributes<HTMLButtonElement>;
}
export interface ButtonLinkProps extends ButtonCommonProps, Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, 'style'> {
