import {useEffect, useState} from 'react';
import {PageConstructor, PageConstructorProvider, type PageContent} from '@gravity-ui/page-constructor';
import {Button, Text} from '@gravity-ui/uikit';

function TrialTimer() {
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const [hasStarted, setHasStarted] = useState(false);

  useEffect(() => {
    if (startedAt === null) return;
    const update = () => setElapsed(Math.floor((Date.now() - startedAt) / 1000));
    update();
    const interval = window.setInterval(update, 1000);
    return () => window.clearInterval(interval);
  }, [startedAt]);

  const time = [Math.floor(elapsed / 3600), Math.floor(elapsed / 60) % 60, elapsed % 60]
    .map((value) => String(value).padStart(2, '0')).join(':');

  function toggleTimer() {
    if (startedAt "'!== null) {
      setElapsed(Math.floor((Date.now() - startedAt) / 1000));
      setStartedAt(null);
    } else {
      setElapsed(0);
      setStartedAt(Date.now());
      setHasStarted(true);
    }
  }

  return (
    <div className="trial">
      <Button view="action" size="xl" className="trial-button" onClick={toggleTimer}>
        {startedAt !== null ? '"'Остановить таймер' : hasStarted ? 'Начать ещё раз' : 'Попробовать Tempo'}
        <span className=\"button-arrow\" aria-hidden=\"true\">↗</span>
      </Button>
      <Text as=\"p\" variant=\"body-1\" color=\"secondary\" className=\"trial-note\">
        {hasStarted ? (
          <><span role=\"timer\" aria-label=\"Время пробной сессии\">{time}</span> · {startedAt "'!== null ? '"'Ваше время под контролем' : 'Пробная сессия завершена'}</>
        ) : 'Пробный таймер · Без регистрации'}
      </Text>
      <span className=\"sr-only\" role=\"status\">
        {hasStarted ? startedAt "'!== null ? '"'Пробный таймер запущен' : "'`Таймер остановлен. Длительность ${time}` : '"''}
      </span>
    </div>
  );
}

const content: PageContent = {
  animated: false,
  blocks: [
    {
      type: 'header-block',
      centered: true,
      width: 'l',
      verticalOffset: '0',
      indent: {top: '0', bottom: '0'},
      overtitle: (
        <div className=\"hero-intro\">
          <Text variant=\"display-1\" className=\"wordmark\">tempo<span className=\"brand-dot\">.</span></Text>
          <Text variant=\"body-1\" className=\"eyebrow\">ВРЕМЯ КОМАНДЫ — В ФОКУСЕ</Text>
        </div>
      ),
      title: '<span class=\"hero-title\">Меньше рутины.<br><span class=\"hero-accent\">Больше времени.</span></span>',
      description: '<p class=\"hero-description\">Простой учёт времени для небольших команд.<br class=\"desktop-break\"> Занимайтесь важным — Tempo поможет понять,<br class=\"desktop-break\"> куда уходят часы.</p>',
    },
    {
      type: 'extended-features-block',
      animated: false,
      indent: {top: 'xl', bottom: 'xl'},
      colSizes: {all: 12, sm: 12, md: 4},
      items: [
        {
          title: '<span class=\"feature-number\">01 /</span>Один клик — и вы в деле',
          text: '<p class=\"feature-description\">Запускайте таймер и возвращайтесь к задаче. Учёт времени, который не отнимает время.</p>',
        },
        {
          title: '<span class=\"feature-number\">02 /</span>Вся команда на виду',
          text: '<p class=\"feature-description\">Понимайте загрузку коллег и распределяйте задачи без лишних сообщений и созвонов.</p>',
        },
        {
          title: '<span class=\"feature-number\">03 /</span>Ясность в каждом часе',
          text: '<p class=\"feature-description\">Видите, сколько времени уходит на проекты. Планируйте на основе фактов, а не ощущений.</p>',
        },
      ],
    },
    {
      type: 'content-layout-block',
      centered: true,
      size: 's',
      textWidth: 'l',
      indent: {top: '0', bottom: '0'},
      textContent: {
        title: '<span class=\"cta-title\">Найдите время для главного.</span>',
        text: '<p class=\"cta-description\">Начните с одной задачи. Остальное — в вашем темпе.</p>',
        buttons: [<TrialTimer key=\"trial\" />],
      },
    },
  ],
};

export function App() {
  return (
    <main className=\"landing\">
      <PageConstructorProvider locale={{lang: 'ru', tld: 'ru'}} theme=\"light\">
        <PageConstructor content={content} />
      </PageConstructorProvider>
    </main>
  );
}
EOF
cat > src/styles.css <<'EOF'
*,
*::before,
*::after {
  box-sizing: border-box;
}

.g-root {
  --g-color-base-brand: var(--g-color-base-utility-heavy);
  --g-color-base-brand-hover: var(--g-color-base-utility-heavy-hover);
  --g-color-base-selection: var(--g-color-base-utility-light);
  --g-color-base-selection-hover: var(--g-color-base-utility-light-hover);
  --g-color-line-brand: var(--g-color-line-utility);
  --g-color-text-brand: var(--g-color-text-utility);
  --g-color-text-brand-heavy: var(--g-color-text-utility-heavy);
  --g-color-text-brand-contrast: var(--g-color-text-light-primary);
  --g-color-text-link: var(--g-color-text-utility);
  --g-color-text-link-hover: var(--g-color-text-utility-heavy);
  --g-color-text-link-visited: var(--g-color-text-utility);
  --g-color-line-focus: var(--g-color-line-utility);
  --g-text-header-1-font-size: 21px;
  --g-text-header-1-line-height: 28px;
  --g-text-display-4-font-size: clamp(40px, 5.6vw, 76px);
  --g-text-display-4-line-height: 1.08;
}

body {
  margin: 0;
  background: var(--g-color-base-background);
  color: var(--g-color-text-primary);
  -webkit-font-smoothing: antialiased;
}

.landing {
  max-width: 1180px;
  margin-inline: auto;
  padding: var(--g-spacing-8) var(--g-spacing-5) calc(var(--g-spacing-10) * 1.5);
  --pc-text-header-color: var(--g-color-text-primary);
}

.hero-intro {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--g-spacing-10) * 1.4);
  padding-bottom: var(--g-spacing-4);
}

.wordmark {
  font-weight: 750;
  letter-spacing: -1.7px;
}

.brand-dot,
.hero-accent {
  color: var(--g-color-text-brand);
}

.eyebrow {
  font-weight: 500;
  letter-spacing: 2px;
  color: var(--g-color-text-secondary);
}

.hero-title {
  display: block;
  font-size: var(--g-text-display-4-font-size);
  line-height: var(--g-text-display-4-line-height);
  font-weight: 650;
  letter-spacing: -3px;
}

.hero-description {
  padding-top: var(--g-spacing-3);
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-3-font-size);
  line-height: 1.65;
}

.feature-number {
  display: block;
  padding: var(--g-spacing-6) 0 var(--g-spacing-6);
  margin-bottom: var(--g-spacing-2);
  border-top: 1px solid var(--g-color-line-generic);
  color: var(--g-color-text-brand);
  font-size: var(--g-text-body-2-font-size);
  font-weight: 500;
  letter-spacing: 1px;
}

.feature-description {
  max-width: 30ch;
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-2-font-size);
  line-height: 1.7;
}

.cta-title {
  display: inline-block;
  padding-top: var(--g-spacing-5);
  font-size: var(--g-text-display-1-font-size);
  line-height: var(--g-text-display-1-line-height);
  font-weight: 600;
  letter-spacing: -0.8px;
}

.cta-description {
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-2-font-size);
}

.trial {
  text-align: center;
  padding-top: var(--g-spacing-2);
}

.trial-button {
  --g-button-border-radius: var(--g-border-radius-l);
  --g-button-padding: var(--g-spacing-6);
  min-width: 224px;
  font-weight: 500;
}

.button-arrow {
  display: inline-block;
  margin-left: var(--g-spacing-5);
  font-size: var(--g-text-header-1-font-size);
}

.trial-note {
  margin: var(--g-spacing-4) 0 0;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 767px) {
  .landing { padding-inline: var(--g-spacing-2); }
  .hero-intro { gap: var(--g-spacing-10); }
  .hero-title { letter-spacing: -1.8px; }
  .eyebrow { letter-spacing: 1.2px; }
  .desktop-break { display: none; }
  .feature-description { max-width: none; }
  .cta-title {
    font-size: var(--g-text-header-2-font-size);
    line-height: var(--g-text-header-2-line-height);
  }
}
EOF"
